def test_github_requires_evaluation_receipt(tmp_path: Path) -> None:
    artifact, digest = _write_artifact(tmp_path, "repo.json", '{"repository":"example/tool"}')
    base = {
        "provider": "github",
        "source_type": "github_repository",
        "repository": "example/tool",
        "retrieval_artifact": artifact,
        "content_sha256": digest,
    }
    assert classify_source_bearing_record(base, base_dir=tmp_path)["source_bearing"] is False
    with_receipt = dict(base, evaluation_receipt={"artifact_path": "github-search-receipt.json"})
    assert classify_source_bearing_record(with_receipt, base_dir=tmp_path)["source_bearing"] is True


def test_source_bearing_summary_counts_only_bound_records(tmp_path: Path) -> None:
    artifact, digest = _write_artifact(tmp_path, "web.json", '{"url":"https://example.com"}')
    summary = summarize_source_bearing_records(
        [
            {
                "provider": "brave",
                "source_type": "web_page",
                "url": "https://example.com",
                "retrieval_artifact": artifact,
                "content_sha256": digest,
                "ok": True,
            },
            {"provider": "codex_knowledge", "ok": True},
        ],
        base_dir=tmp_path,
    )
    assert summary["source_bearing_provider_count"] == 1
    assert summary["source_bearing_evidence_count"] == 1
    assert summary["model_synthesis_present"] is True
    assert summary["research_evidence_sufficient"] is True


def test_fixture_eval_writes_positive_and_negative_packets(tmp_path: Path) -> None:
    receipt = run_source_bearing_fixture_eval(tmp_path)
    assert receipt["status"] == "PASS", receipt
    valid = json.loads((tmp_path / receipt["valid_packet"]).read_text())
    model_only = json.loads((tmp_path / receipt["model_only_negative_receipt"]).read_text())
    skipped = json.loads((tmp_path / receipt["skipped_provider_negative_receipt"]).read_text())
    assert valid["source_bearing_evidence_count"] >= 2
    assert model_only["source_bearing_evidence_count"] == 0
    assert skipped["source_bearing_evidence_count"] == 0
    assert (tmp_path / receipt["valid_hack_scan_request"]).exists()
